const Tbl=({cols,data,onRow})=><div style={{borderRadius:10,border:"1px solid "+C.bd,overflow:"auto",background:C.sf,maxWidth:"100%",maxHeight:"calc(100vh - 170px)"}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:13,minWidth:600}}><thead><tr>{cols.map((c,i)=><th key={i} style={{padding:"10px 12px",textAlign:"left",background:C.thBg,color:C.tD,fontSize:10,textTransform:"uppercase",letterSpacing:.8,borderBottom:"2px solid "+C.acc,whiteSpace:"nowrap",fontWeight:700,position:"sticky",top:0,zIndex:1}}>{c.label}</th>)}</tr></thead><tbody>{data.length===0?<tr><td colSpan={cols.length} style={{padding:30,textAlign:"center",color:C.tM}}>Nessun dato</td></tr>:data.map((row,ri)=>row._blank?<tr key={"bl"+ri}><td colSpan={cols.length} style={{padding:4,background:C.bg}}></td></tr>:row._sub?<tr key={"sub"+ri} style={{background:row._level==="tipo"?C.accL:row._level==="lav"?C.gD:C.zebra,borderTop:row._level==="tipo"?"2px solid "+C.acc:row._level==="lav"?"2px solid "+C.g:"1px solid "+C.bd}}>{cols.map((c,ci)=><td key={ci} style={{padding:"7px 12px",fontWeight:row._level==="tipo"?800:700,fontSize:row._level==="tipo"?12:11,color:row._level==="tipo"?C.acc:row._level==="lav"?C.g:C.tD,whiteSpace:"nowrap",fontStyle:row._level==="cal"?"italic":"normal"}}>{c.subRender?c.subRender(row):""}</td>)}</tr>:<tr key={row.id||ri} onClick={()=>onRow&&onRow(row)} style={{cursor:onRow?"pointer":"default",background:ri%2===0?C.sf:C.zebra,transition:"background .15s"}} onMouseEnter={e=>{e.currentTarget.style.background=C.sfH}} onMouseLeave={e=>{e.currentTarget.style.background=ri%2===0?C.sf:C.zebra}}>{cols.map((c,ci)=><td key={ci} style={{padding:"9px 12px",borderBottom:"1px solid "+C.bd+"66",whiteSpace:"nowrap",color:C.t}}>{c.render?c.render(row):row[c.key]}</td>)}</tr>)}</tbody></table></div>;
