function RicercaPage({lotti}){const[q,setQ]=useState("");const av=lotti.filter(l=>dsp(l)>0);const res=q.length<2?[]:av.filter(l=>[l.lotto,l.imballo,l.desc1,l.desc2,l.desc3,l.magazzino,l.acquirente,l.contratto].some(v=>v&&String(v).toUpperCase().includes(q.toUpperCase()))).sort(stdSort);return <div><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:24}}><h1 style={{fontSize:28,fontWeight:900,color:C.t,margin:0,fontFamily:"'Playfair Display',serif"}}>Ricerca</h1>{res.length>0&&<XBtn data={res} cols={XC.giacenze} name="ricerca"/>}</div><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Cerca lotto, tipo, calibro, magazzino, acquirente..." style={{width:"100%",padding:"14px 20px",background:C.sf,border:"2px solid "+(q.length>=2?C.acc+"66":C.bd),borderRadius:10,color:C.t,fontSize:16,outline:"none",marginBottom:16,boxSizing:"border-box"}} data-no-print/>{q.length>=2&&<><p style={{color:C.tM,fontSize:13,marginBottom:12}}>{res.length} risultati</p><Tbl cols={[{label:"Tipo",render:r=><Badge color={TC[r.desc1]||C.acc} bg={(TC[r.desc1]||C.acc)+"18"}>{r.desc1}</Badge>},{key:"desc2",label:"Lav."},{key:"desc3",label:"Cal."},{key:"lotto",label:"Lotto"},{key:"imballo",label:"Imballo"},{label:"Sett.",render:r=><span style={{fontSize:11,color:C.tM}}>{r.sett_prod?r.sett_prod+"/"+r.anno:"-"}</span>},{label:"Disp.",render:r=><span style={{fontFamily:"'DM Mono',monospace",fontWeight:700,color:C.acc}}>{dsp(r).toLocaleString("it-IT")} kg</span>},{key:"magazzino",label:"Mag."},{label:"M.O.",render:r=><span style={{fontFamily:"'DM Mono',monospace",fontSize:12,color:moP(r)>4?C.r:moP(r)>2?C.o:C.g}}>{pct(r.mo)}</span>},{label:"C.O.",render:r=><span style={{fontFamily:"'DM Mono',monospace",fontSize:12,color:coP(r)>4?C.r:coP(r)>2?C.o:C.g}}>{pct(r.co)}</span>},{key:"contratto",label:"Contr."},{key:"acquirente",label:"Acq."}]} data={res}/></>}</div>;}

// === STORICO ===
function StoricoPage(){const[dt,setDt]=useState(new Date().toISOString().split("T")[0]);const[ld,setLd]=useState(false);const[snap,setSnap]=useState(null);const xCols=[{key:"desc1",label:"Tipo"},{key:"desc2",label:"Lav."},{key:"desc3",label:"Cal."},{key:"lotto",label:"Lotto"},{key:"imballo",label:"Imballo"},{key:"ent",label:"Entrate"},{key:"usc",label:"Uscite"},{key:"disp",label:"Disp."},{key:"magazzino",label:"Mag."}];const calc=useCallback(async()=>{setLd(true);const{data:movs}=await supabase.from("movimenti").select("*").order("data").order("id");const filtered=(movs||[]).filter(m=>{const md=String(m.data||"").split("T")[0];return md<=dt});const mp={};filtered.forEach(m=>{const k=m.lotto+"||"+m.imballo;if(m.tipo==="ENTRATA"){if(!mp[k])mp[k]={lotto:m.lotto,imballo:m.imballo,desc1:m.desc1,desc2:m.desc2,desc3:m.desc3,magazzino:m.magazzino,ent:0,usc:0};mp[k].ent+=m.qta;mp[k].magazzino=m.magazzino}else if((m.tipo==="USCITA"||m.tipo==="TRASFORMAZIONE")&&mp[k])mp[k].usc+=m.qta;else if(m.tipo==="TRASFERIMENTO"&&mp[k]){if(String(m.contratto_id||"").startsWith("SPLIT|"))mp[k].usc+=m.qta;else mp[k].magazzino=m.magazzino}});const ls=Object.values(mp).map(l=>({...l,disp:l.ent-l.usc})).filter(l=>l.ent>0).sort(stdSort);const tot=ls.reduce((s,l)=>s+Math.max(0,l.disp),0);const av=ls.filter(l=>l.disp>0);setSnap({dt,ls,av,tot,nm:filtered.length});setLd(false)},[dt]);return <div><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:24}}><div><h1 style={{fontSize:28,fontWeight:900,color:C.t,margin:0,fontFamily:"'Playfair Display',serif"}}>Storico</h1><p style={{color:C.tM,margin:"4px 0 0",fontSize:13}}>Giacenze a una data</p></div>{snap&&<XBtn data={snap.av} cols={xCols} name={"storico_"+snap.dt}/>}</div><GCard style={{marginBottom:24,display:"flex",gap:16,alignItems:"flex-end"}} data-no-print><div style={{display:"flex",flexDirection:"column",gap:4}}><label style={{fontSize:10,color:C.tD,textTransform:"uppercase",letterSpacing:1,fontWeight:600}}>Data</label><input type="date" value={dt} onChange={e=>setDt(e.target.value)} style={{padding:"10px 14px",background:C.sf,border:"2px solid "+C.acc+"66",borderRadius:8,color:C.t,fontSize:16,outline:"none",fontFamily:"'DM Mono',monospace"}}/></div><Btn primary onClick={calc} disabled={ld}>{ld?"Calcolo...":"Visualizza al "+fmtD(dt)}</Btn></GCard>{snap&&<><div style={{display:"flex",gap:14,flexWrap:"wrap",marginBottom:20}}><GCard><div style={{fontSize:10,color:C.tD,textTransform:"uppercase",letterSpacing:1.5,fontWeight:600}}>Giacenza al {fmtD(snap.dt)}</div><div style={{fontSize:26,fontWeight:900,color:C.acc,fontFamily:"'DM Mono',monospace",marginTop:6}}>{snap.tot.toLocaleString("it-IT")} kg</div><div style={{fontSize:12,color:C.tM,marginTop:4}}>{snap.av.length} lotti</div></GCard></div><Tbl cols={[{label:"Tipo",render:r=><Badge color={TC[r.desc1]||C.acc} bg={(TC[r.desc1]||C.acc)+"18"}>{r.desc1}</Badge>},{key:"desc2",label:"Lav."},{key:"desc3",label:"Cal."},{key:"lotto",label:"Lotto"},{key:"imballo",label:"Imballo"},{label:"Entrate",render:r=><span style={{fontFamily:"'DM Mono',monospace",color:C.g}}>{r.ent.toLocaleString("it-IT")}</span>},{label:"Uscite",render:r=><span style={{fontFamily:"'DM Mono',monospace",color:r.usc>0?C.r:C.tM}}>{r.usc.toLocaleString("it-IT")}</span>},{label:"Disp.",render:r=><span style={{fontFamily:"'DM Mono',monospace",fontWeight:700,color:r.disp>0?C.acc:C.r}}>{r.disp.toLocaleString("it-IT")} kg</span>},{key:"magazzino",label:"Mag."}]} data={snap.ls}/><div style={{marginTop:14,padding:"12px 20px",background:C.accL,borderRadius:8,display:"flex",justifyContent:"space-between"}}><span style={{fontWeight:700,color:C.acc}}>TOTALE</span><span style={{fontWeight:900,color:C.acc,fontFamily:"'DM Mono',monospace"}}>{snap.tot.toLocaleString("it-IT")} kg</span></div></>}{!snap&&!ld&&<div style={{textAlign:"center",padding:60,color:C.tM}}><p>Seleziona una data e clicca Visualizza</p></div>}</div>;}

// === STORICO MOVIMENTI ===
function StoricoMovPage({movimenti,lotti,contratti,reload}){const[undoId,setUndoId]=useState(null);const[msg,setMsg]=useState(null);const[selMov,setSelMov]=useState(null);const[fT,setFT]=useState("");const[fD1,setFD1]=useState("");const[fD2,setFD2]=useState("");const[fL,setFL]=useState("");const flash=(t,x)=>{setMsg({t,x});setTimeout(()=>setMsg(null),4000)};
  const handleUndo=async r=>{try{
    if(r.tipo==="ENTRATA"){
      if(r.lotto_id){const{data:lot}=await supabase.from("lotti").select("id,mov,lotto_padre").eq("id",r.lotto_id).maybeSingle();if(lot){if(lot.lotto_padre){flash("err","Questo lotto deriva da una trasformazione: annulla la riga TRASFORMAZIONE corrispondente");return}if((lot.mov||0)>0){flash("err","Il lotto ha gia movimenti: annulla prima quelli");return}await supabase.from("lotti").delete().eq("id",lot.id)}}
      else{const{data:lots}=await supabase.from("lotti").select("id").match({imballo:r.imballo,lotto:r.lotto,q_iniz:r.qta}).limit(1);if(lots&&lots[0])await supabase.from("lotti").delete().eq("id",lots[0].id)}}
    else if(r.tipo==="USCITA"){
      if(r.lotto_id)await supabase.rpc("incrementa_mov",{lid:r.lotto_id,q:-r.qta});
      else{const{data:lots}=await supabase.from("lotti").select("*").match({imballo:r.imballo,lotto:r.lotto,desc1:r.desc1,desc2:r.desc2,desc3:r.desc3}).limit(1);if(lots&&lots[0])await supabase.from("lotti").update({mov:Math.max(0,lots[0].mov-r.qta)}).eq("id",lots[0].id)}
      if(r.contratto_id&&contratti.some(c=>c.id===r.contratto_id))await supabase.rpc("incrementa_evasa",{cid:r.contratto_id,q:-r.qta})}
    else if(r.tipo==="TRASFORMAZIONE"){const childId=Number(String(r.contratto_id||"").replace("TRASF:",""));if(!childId){flash("err","Movimento trasformazione senza riferimento al lotto prodotto");return}const{data:child}=await supabase.from("lotti").select("id,mov").eq("id",childId).maybeSingle();if(child&&(child.mov||0)>0){flash("err","Il lotto prodotto ha gia movimenti propri: annulla prima quelli");return}const{data:disc}=await supabase.from("movimenti").select("id,lotto_id,qta").eq("tipo","TRASFORMAZIONE").eq("contratto_id","TRASF:"+childId);for(const d of(disc||[])){if(d.lotto_id)await supabase.rpc("incrementa_mov",{lid:d.lotto_id,q:-d.qta})}if(child)await supabase.from("lotti").delete().eq("id",child.id);await supabase.from("movimenti").delete().match({tipo:"ENTRATA",lotto_id:childId});await supabase.from("movimenti").delete().eq("tipo","TRASFORMAZIONE").eq("contratto_id","TRASF:"+childId)}
    else if(r.tipo==="TRASFERIMENTO"){
      const cid=String(r.contratto_id||"");
      if(r.lotto_id&&cid.startsWith("SPLIT|")){const{data:child}=await supabase.from("lotti").select("id,mov,lotto_padre").eq("id",r.lotto_id).maybeSingle();if(child){if((child.mov||0)>0){flash("err","Il lotto trasferito ha gia movimenti: annulla prima quelli");return}if(child.lotto_padre)await supabase.rpc("incrementa_mov",{lid:child.lotto_padre,q:-r.qta});await supabase.from("lotti").delete().eq("id",child.id)}await supabase.from("movimenti").delete().match({tipo:"ENTRATA",lotto_id:r.lotto_id})}
      else if(r.lotto_id&&cid){await supabase.from("lotti").update({magazzino:cid}).eq("id",r.lotto_id)}
      else if(cid){await supabase.from("lotti").update({magazzino:cid}).match({imballo:r.imballo,lotto:r.lotto,desc1:r.desc1,magazzino:r.magazzino}).limit(1)}}
    await supabase.from("movimenti").delete().eq("id",r.id);setUndoId(null);setSelMov(null);flash("ok","Annullato");await reload()}catch(e){flash("err",e.message)}};const enriched=useMemo(()=>movimenti.map(m=>{const lot=(m.lotto_id?lotti.find(l=>l.id===m.lotto_id):null)||lotti.find(l=>l.lotto===m.lotto&&l.imballo===m.imballo);return{...m,lot,cliente:lot?.contratto?contratti.find(c=>c.id===lot.contratto)?.cliente||"":"",acquirente:lot?.acquirente||""}}),[movimenti,lotti,contratti]);const shown=useMemo(()=>enriched.filter(m=>{if(fT&&m.tipo!==fT)return false;const md=String(m.data||"").split("T")[0];if(fD1&&md<fD1)return false;if(fD2&&md>fD2)return false;if(fL&&!(((m.lotto||"")+" "+(m.imballo||"")).toUpperCase().includes(fL.toUpperCase())))return false;return true}),[enriched,fT,fD1,fD2,fL]);const selLot=selMov?enriched.find(m=>m.id===selMov)?.lot:null;return <div><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:24}}><div><h1 style={{fontSize:28,fontWeight:900,color:C.t,margin:0,fontFamily:"'Playfair Display',serif"}}>Storico Movimenti</h1><p style={{color:C.tM,margin:"4px 0 0",fontSize:13}}>{shown.length} movimenti — clicca per dettaglio</p></div><XBtn data={shown} cols={XC.movimenti} name="storico_movimenti"/></div><Msg msg={msg}/><div style={{display:"flex",gap:10,marginBottom:14,flexWrap:"wrap"}} data-no-print><Sel label="Movimento" value={fT} onChange={setFT} options={[{value:"",label:"Tutti"},{value:"ENTRATA",label:"Entrata"},{value:"USCITA",label:"Uscita"},{value:"TRASFERIMENTO",label:"Trasferimento"},{value:"TRASFORMAZIONE",label:"Trasformazione"}]}/><Inp label="Da" type="date" value={fD1} onChange={setFD1}/><Inp label="A" type="date" value={fD2} onChange={setFD2}/><Inp label="Cerca lotto/imballo" value={fL} onChange={setFL} placeholder="SO11..." style={{flex:"1 1 180px"}}/>{(fT||fD1||fD2||fL)&&<div style={{display:"flex",alignItems:"flex-end"}}><Btn small onClick={()=>{setFT("");setFD1("");setFD2("");setFL("")}}>Azzera</Btn></div>}</div>{selLot&&<div style={{padding:"12px 16px",background:C.accL,borderRadius:8,marginBottom:14,display:"flex",gap:16,flexWrap:"wrap",alignItems:"center",animation:"fadeUp .2s both"}} data-no-print><span style={{fontWeight:700,color:C.acc}}>{selLot.lotto} - {selLot.imballo}</span><span>M.V. <b>{pct(selLot.mv)}</b></span><span>M.O. <b style={{color:moP(selLot)>4?C.r:moP(selLot)>2?C.o:C.g}}>{pct(selLot.mo)}</b></span><span>C.V. <b>{pct(selLot.cv)}</b></span><span>C.O. <b style={{color:coP(selLot)>4?C.r:coP(selLot)>2?C.o:C.g}}>{pct(selLot.co)}</b></span><span>C.E. <b>{pct(selLot.ce)}</b></span><span>RT <b>{pct(selLot.rt)}</b></span><Btn small onClick={()=>setSelMov(null)}>Chiudi</Btn></div>}{selLot&&selLot.lotto_padre&&<div style={{padding:"12px 16px",background:C.zebra,borderRadius:8,marginBottom:14}} data-no-print><Tracciabilita lot={selLot}/></div>}<Tbl cols={[{label:"Mov.",render:r=><Badge color={r.tipo==="ENTRATA"?C.g:r.tipo==="USCITA"?C.r:r.tipo==="TRASFORMAZIONE"?C.acc:C.b} bg={r.tipo==="ENTRATA"?C.gD:r.tipo==="USCITA"?C.rD:r.tipo==="TRASFORMAZIONE"?C.accL:C.bD}>{r.tipo}</Badge>},{label:"Data",render:r=>fmtD(r.data)},{label:"Tipo",render:r=><Badge color={TC[r.desc1]||C.acc} bg={(TC[r.desc1]||C.acc)+"18"}>{r.desc1}</Badge>},{key:"desc2",label:"Lav."},{key:"desc3",label:"Cal."},{key:"lotto",label:"Lotto"},{key:"imballo",label:"Imballo"},{label:"Qta",render:r=><span style={{fontFamily:"'DM Mono',monospace",fontWeight:700}}>{r.qta?.toLocaleString("it-IT")}</span>},{label:"DDT",render:r=>r.ddt?<span style={{fontFamily:"'DM Mono',monospace",fontSize:12,color:C.t}}>{r.ddt}</span>:<span style={{color:C.tM}}>-</span>},{key:"magazzino",label:"Mag."},{label:"Contr.",render:r=>{const cid=String(r.contratto_id||"");if(!cid)return <span style={{color:C.tM}}>-</span>;if(r.tipo==="TRASFORMAZIONE")return <span style={{fontSize:11,color:C.acc}}>{"\u21b3 prodotto"}</span>;if(r.tipo==="TRASFERIMENTO")return <span style={{fontSize:11,color:C.tM}}>da {cid.replace("SPLIT|","")}</span>;return <Badge color={C.b} bg={C.bD}>{cid}</Badge>}},{key:"cliente",label:"Cliente"},{key:"acquirente",label:"Acq."},{label:"Utente",render:r=><span style={{fontSize:11,color:C.tM}}>{(r.utente||"").split("@")[0]}</span>},{label:"",render:r=>undoId===r.id?<div style={{display:"flex",gap:4,alignItems:"center"}}><span style={{fontSize:11,color:C.o}}>Sicuro?</span><button onClick={e=>{e.stopPropagation();handleUndo(r)}} style={{background:C.r,border:"none",color:"#fff",cursor:"pointer",fontSize:11,padding:"4px 10px",borderRadius:6,fontWeight:700}}>Si</button><button onClick={e=>{e.stopPropagation();setUndoId(null)}} style={{background:C.sf,border:"1px solid "+C.bd,color:C.tD,cursor:"pointer",fontSize:11,padding:"4px 8px",borderRadius:6}}>No</button></div>:<button onClick={e=>{e.stopPropagation();setUndoId(r.id)}} style={{background:"none",border:"none",color:C.r,cursor:"pointer",fontSize:12,opacity:.7}}>Annulla</button>}]} data={shown} onRow={r=>setSelMov(selMov===r.id?null:r.id)}/></div>;}

// === UTENTI ===
function UtentiPage(){const[users,setUsers]=useState([]);const[msg,setMsg]=useState(null);const[showN,setShowN]=useState(false);const[nE,setNE]=useState("");const[nP,setNP]=useState("");const[nN,setNN]=useState("");const[nR,setNR]=useState("operatore");const[cfId,setCfId]=useState(null);const flash=(t,x)=>{setMsg({t,x});setTimeout(()=>setMsg(null),4000)};const load=useCallback(async()=>{const{data}=await supabase.from("user_profiles").select("*").order("created_at");setUsers(data||[])},[]);useEffect(()=>{load()},[load]);const create=async()=>{if(!nE||!nP){flash("err","Email e password obbligatori");return}const{data,error}=await supabase.functions.invoke("crea-utente",{body:{email:nE,password:nP,nome:nN,ruolo:nR}});if(error||data?.error){flash("err","Errore: "+(data?.error||error.message)+". Verifica che la Edge Function crea-utente sia deployata su Supabase.");return}setShowN(false);setNE("");setNP("");setNN("");flash("ok","Utente creato");await load()};const toggle=async u=>{const nr=u.ruolo==="admin"?"operatore":"admin";if(u.ruolo==="admin"&&users.filter(x=>x.ruolo==="admin").length<=1){flash("err","Non puoi rimuovere l'ultimo amministratore: prima promuovi un altro utente ad admin.");setCfId(null);return}await supabase.from("user_profiles").update({ruolo:nr}).eq("id",u.id);setCfId(null);flash("ok",nr==="admin"?"Utente promosso ad admin":"Utente reso operatore");await load()};return <div><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:20}}><h1 style={{fontSize:28,fontWeight:900,color:C.t,margin:0,fontFamily:"'Playfair Display',serif"}}>Utenti</h1><Btn primary onClick={()=>setShowN(true)}>+ Nuovo</Btn></div><Msg msg={msg}/>{showN&&<GCard style={{marginBottom:20}}><h3 style={{fontSize:16,fontWeight:800,color:C.acc,margin:"0 0 16px"}}>Nuovo Utente</h3><div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(200px,1fr))",gap:12}}><Inp label="Email *" value={nE} onChange={setNE} placeholder="mario@assofrutti.it"/><Inp label="Password *" value={nP} onChange={setNP} type="password"/><Inp label="Nome" value={nN} onChange={setNN}/><Sel label="Ruolo" value={nR} onChange={setNR} options={[{value:"operatore",label:"Operatore"},{value:"admin",label:"Admin"}]}/></div><div style={{marginTop:16,display:"flex",justifyContent:"flex-end",gap:10}}><Btn onClick={()=>setShowN(false)}>Annulla</Btn><Btn primary onClick={create}>Crea</Btn></div></GCard>}<Tbl cols={[{key:"email",label:"Email"},{key:"nome",label:"Nome"},{label:"Ruolo",render:r=><Badge color={r.ruolo==="admin"?C.acc:C.b} bg={r.ruolo==="admin"?C.accL:C.bD}>{r.ruolo}</Badge>},{label:"",render:r=>{const lastAdmin=r.ruolo==="admin"&&users.filter(x=>x.ruolo==="admin").length<=1;return cfId===r.id?<span style={{display:"flex",gap:6,alignItems:"center"}}><span style={{fontSize:11,color:C.o}}>{r.ruolo==="admin"?"Declassare a operatore?":"Promuovere ad admin?"}</span><button onClick={()=>toggle(r)} style={{background:C.acc,border:"none",color:"#fff",cursor:"pointer",fontSize:11,padding:"4px 10px",borderRadius:6,fontWeight:700}}>Conferma</button><button onClick={()=>setCfId(null)} style={{background:C.sf,border:"1px solid "+C.bd,color:C.tD,cursor:"pointer",fontSize:11,padding:"4px 8px",borderRadius:6}}>Annulla</button></span>:lastAdmin?<Btn small disabled style={{opacity:.5}}>Unico admin</Btn>:<Btn small onClick={()=>setCfId(r.id)}>{r.ruolo==="admin"?"Rendi Operatore":"Rendi Admin"}</Btn>}}]} data={users}/></div>;}

// === MAIN APP ===
const NAV=[{id:"dashboard",icon:"\u25c6",label:"Dashboard"},{id:"entrata",icon:"\u2193",label:"Entrata"},{id:"trasformazione",icon:"\u2699",label:"Trasformazione"},{id:"controllo",icon:"\u2713",label:"Controllo semi."},{id:"giacenze",icon:"\u25a3",label:"Giacenze"},{id:"scanner",icon:"\u25a6",label:"Scanner"},{id:"contratti",icon:"\u25c8",label:"Contratti"},{id:"clienti",icon:"\u263a",label:"Clienti"},{id:"ricerca",icon:"\u2315",label:"Ricerca"},{id:"storico",icon:"\u23f0",label:"Storico"},{id:"storicomov",icon:"\u2630",label:"Storico Mov."}];
function useIsMobile(bp){const lim=bp||768;const[m,setM]=useState(typeof window!=="undefined"&&window.innerWidth<=lim);useEffect(()=>{const f=()=>setM(window.innerWidth<=lim);window.addEventListener("resize",f);f();return()=>window.removeEventListener("resize",f)},[lim]);return m}
export default function App(){
  const[session,setSession]=useState(null);const[profile,setProfile]=useState(null);const[authLd,setAuthLd]=useState(true);const[recovery,setRecovery]=useState(false);
  const[page,setPage]=useState("dashboard");const[lotti,setLotti]=useState([]);const[contratti,setContratti]=useState([]);const[movimenti,setMovimenti]=useState([]);const[sO,setSO]=useState(true);const[drawer,setDrawer]=useState(false);const isMobile=useIsMobile(768);const[dbErr,setDbErr]=useState(null);const[dashFilter,setDashFilter]=useState(null);
  const[theme,setTheme]=useState("light");C=theme==="dark"?DARK:LIGHT;GRP=theme==="dark"?GRP_D:GRP_L;
  const[annata,setAnnata]=useState(()=>{try{return window.localStorage.getItem("af_annata")||String(CAMP())}catch(e){return String(CAMP())}});
  const setAnn=v=>{setAnnata(v);try{window.localStorage.setItem("af_annata",v)}catch(e){}};
  const anni=useMemo(()=>{const s=[...new Set(lotti.map(l=>l.anno_raccolta||l.anno).filter(Boolean))].sort((a,b)=>b-a);if(!s.includes(CAMP()))s.unshift(CAMP());return s},[lotti]);
  const lottiF=useMemo(()=>annata==="ALL"?lotti:lotti.filter(l=>String(l.anno_raccolta||l.anno)===annata),[lotti,annata]);
  const toggleTheme=t=>{setTheme(t);try{window.localStorage.setItem("af_theme",t)}catch(e){}};
  useEffect(()=>{try{const s=window.localStorage.getItem("af_theme");if(s)setTheme(s)}catch(e){}},[]);
  useEffect(()=>{supabase.auth.getSession().then(({data:{session:s}})=>{setSession(s);if(!s)setAuthLd(false)});const{data:{subscription}}=supabase.auth.onAuthStateChange((ev,s)=>{setSession(s);if(ev==="PASSWORD_RECOVERY")setRecovery(true);if(!s){setProfile(null);setAuthLd(false)}});return()=>subscription.unsubscribe()},[]);
  useEffect(()=>{if(!session?.user)return;CUR_EMAIL=session.user.email||"";supabase.from("user_profiles").select("*").eq("id",session.user.id).single().then(({data})=>{setProfile(data);setAuthLd(false)})},[session]);
  const loadAll=useCallback(async()=>{try{const[lr,cr,mr]=await Promise.all([supabase.from("lotti").select("*").order("id"),supabase.from("contratti").select("*").order("id"),supabase.from("movimenti").select("*").order("id",{ascending:false}).limit(5000)]);if(lr.error)throw lr.error;setLotti(lr.data||[]);setContratti(cr.data||[]);setMovimenti(mr.data||[]);setDbErr(null)}catch(e){setDbErr(e.message)}},[]);
  useEffect(()=>{if(session)loadAll()},[session,loadAll]);
  if(authLd)return <div style={{height:"100vh",display:"flex",alignItems:"center",justifyContent:"center",background:C.bg,color:C.acc,fontSize:18,fontFamily:"'DM Sans',sans-serif"}}><style>{CSS}</style>Caricamento...</div>;
  if(!session)return <LoginPage/>;
  if(recovery)return <NewPasswordPage onDone={()=>setRecovery(false)}/>;
  if(dbErr)return <div style={{height:"100vh",display:"flex",alignItems:"center",justifyContent:"center",background:C.bg,flexDirection:"column",gap:16,fontFamily:"'DM Sans',sans-serif"}}><style>{CSS}</style><div style={{color:C.r,fontSize:18,fontWeight:700}}>Errore connessione</div><div style={{color:C.tM,fontSize:13,maxWidth:400,textAlign:"center"}}>{dbErr}</div><Btn primary onClick={loadAll}>Riprova</Btn></div>;
  const isAdm=profile?.ruolo==="admin";const navItems=[...NAV,...(isAdm?[{id:"lotti",icon:"\u25a4",label:"Lotti"},{id:"utenti",icon:"\u2699",label:"Utenti"}]:[])];
  const logout=async()=>{await supabase.auth.signOut()};const goPage=(p,filter)=>{setPage(p);setDashFilter(filter||null)};
  const pg=()=>{switch(page){case"dashboard":return <DashboardPage lotti={lottiF} contratti={contratti} movimenti={movimenti} goPage={goPage}/>;case"entrata":return <MovimentiPage mode="ENTRATA" lotti={lottiF} contratti={contratti} reload={loadAll}/>;case"trasformazione":return <MovimentiPage mode="TRASFORMAZIONE" lotti={lottiF} contratti={contratti} reload={loadAll}/>;case"controllo":return <ControlloSemiPage lotti={lotti} movimenti={movimenti}/>;case"scanner":return <ScannerPage lotti={lotti} contratti={contratti} movimenti={movimenti} reload={loadAll} isAdm={isAdm}/>;case"giacenze":return <GiacenzePage lotti={lottiF} contratti={contratti} reload={loadAll} isAdm={isAdm} dashFilter={dashFilter} clearFilter={()=>{setDashFilter(null);setPage("dashboard")}}/>;case"lotti":return isAdm?<LottiPage lotti={lottiF} reload={loadAll} isAdm={isAdm}/>:null;case"contratti":return <ContrattiPage contratti={contratti} lotti={lotti} movimenti={movimenti} reload={loadAll} isAdm={isAdm} dashFilter={dashFilter}/>;case"clienti":return <ClientiPage lotti={lotti} movimenti={movimenti}/>;case"ricerca":return <RicercaPage lotti={lottiF}/>;case"storico":return <StoricoPage/>;case"storicomov":return <StoricoMovPage movimenti={movimenti} lotti={lotti} contratti={contratti} reload={loadAll}/>;case"utenti":return isAdm?<UtentiPage/>:null;default:return null}};
  if(isMobile)return <div style={{height:"100vh",background:C.bg,fontFamily:"'DM Sans','Segoe UI',sans-serif",color:C.t,display:"flex",flexDirection:"column",overflow:"hidden"}}><style>{CSS}</style>
    <div data-no-print style={{display:"flex",alignItems:"center",gap:10,padding:"10px 12px",background:C.sf,borderBottom:"1px solid "+C.bd,flexShrink:0}}><button onClick={()=>setDrawer(true)} aria-label="Menu" style={{width:40,height:40,borderRadius:10,border:"1px solid "+C.bd,background:"transparent",color:C.t,fontSize:18,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>{"\u2630"}</button><div style={{width:30,height:30,borderRadius:8,background:"linear-gradient(135deg,"+C.acc+","+C.accD+")",display:"flex",alignItems:"center",justifyContent:"center",fontSize:13,fontWeight:900,color:"#fff",flexShrink:0}}>A</div><div style={{fontSize:14,fontWeight:800,color:C.acc,letterSpacing:1}}>ASSOFRUTTI</div>{annata!=="ALL"&&<span style={{marginLeft:"auto",fontSize:11,color:C.tD,fontWeight:600}}>Camp. <b style={{color:C.acc}}>{String(annata).slice(-2)}</b></span>}</div>
    {drawer&&<div onClick={()=>setDrawer(false)} data-no-print style={{position:"fixed",inset:0,background:"rgba(0,0,0,.55)",zIndex:60}}/>}
    <div data-no-print style={{position:"fixed",top:0,left:0,bottom:0,width:270,maxWidth:"82vw",background:C.sf,borderRight:"1px solid "+C.bd,zIndex:61,transform:drawer?"translateX(0)":"translateX(-105%)",transition:"transform .25s",display:"flex",flexDirection:"column",overflow:"hidden"}}>
      <div style={{padding:"16px",borderBottom:"1px solid "+C.bd,display:"flex",alignItems:"center",gap:12}}><div style={{width:34,height:34,borderRadius:10,background:"linear-gradient(135deg,"+C.acc+","+C.accD+")",display:"flex",alignItems:"center",justifyContent:"center",fontSize:15,fontWeight:900,color:"#fff"}}>A</div><div><div style={{fontSize:14,fontWeight:800,color:C.acc,letterSpacing:1}}>ASSOFRUTTI</div><div style={{fontSize:9,color:C.tM,letterSpacing:2,marginTop:2}}>MAGAZZINO</div></div><button onClick={()=>setDrawer(false)} style={{marginLeft:"auto",background:"none",border:"none",color:C.tM,fontSize:24,cursor:"pointer",lineHeight:1}}>{"\u00d7"}</button></div>
      <nav style={{flex:1,padding:"10px",overflowY:"auto"}}>{navItems.map(item=><div key={item.id} onClick={()=>{goPage(item.id);setDrawer(false)}} style={{display:"flex",alignItems:"center",gap:12,padding:"12px",borderRadius:8,marginBottom:3,cursor:"pointer",background:page===item.id?C.accL:"transparent",borderLeft:page===item.id?"3px solid "+C.acc:"3px solid transparent"}}><span style={{fontSize:16,opacity:page===item.id?1:.45}}>{item.icon}</span><span style={{fontSize:15,fontWeight:page===item.id?700:500,color:page===item.id?C.acc:C.tD}}>{item.label}</span></div>)}</nav>
      <div style={{padding:"14px 16px",borderTop:"1px solid "+C.bd}}><div style={{marginBottom:12}}><Sel label="Campagna" value={annata} onChange={setAnn} options={[...anni.map(a=>({value:String(a),label:"Campagna "+a})),{value:"ALL",label:"Tutte le annate"}]}/></div><div style={{display:"flex",gap:6,marginBottom:12}}><button onClick={()=>toggleTheme("light")} style={{flex:1,padding:"8px",borderRadius:6,border:"1px solid "+(theme==="light"?C.acc:C.bd),background:theme==="light"?C.accL:"transparent",cursor:"pointer",fontSize:13,color:theme==="light"?C.acc:C.tM,fontWeight:600}}>{"\u2600 Chiaro"}</button><button onClick={()=>toggleTheme("dark")} style={{flex:1,padding:"8px",borderRadius:6,border:"1px solid "+(theme==="dark"?C.acc:C.bd),background:theme==="dark"?C.accL:"transparent",cursor:"pointer",fontSize:13,color:theme==="dark"?C.acc:C.tM,fontWeight:600}}>{"\u263e Scuro"}</button></div><div style={{fontSize:12,color:C.tD,marginBottom:6,fontWeight:500}}>{profile?.nome||session?.user?.email}</div><Badge color={isAdm?C.acc:C.b} bg={isAdm?C.accL:C.bD}>{profile?.ruolo||"..."}</Badge><div style={{display:"flex",gap:8,marginTop:12}}><Btn small onClick={loadAll} style={{flex:1}}>Aggiorna</Btn><Btn small onClick={logout} style={{flex:1}}>Esci</Btn></div></div>
    </div>
    <div style={{flex:1,overflow:"auto",padding:"14px 12px",background:C.bg}}>{pg()}</div>
  </div>;
  return <div style={{display:"flex",height:"100vh",background:C.bg,fontFamily:"'DM Sans','Segoe UI',sans-serif",color:C.t,overflow:"hidden"}}><style>{CSS}</style>
    <div data-no-print style={{width:sO?220:60,background:C.sf,borderRight:"1px solid "+C.bd,display:"flex",flexDirection:"column",transition:"width .25s",flexShrink:0,overflow:"hidden"}}><div style={{padding:sO?"18px 16px":"18px 14px",borderBottom:"1px solid "+C.bd,display:"flex",alignItems:"center",gap:12,cursor:"pointer",minHeight:62}} onClick={()=>setSO(!sO)}><div style={{width:34,height:34,borderRadius:10,background:"linear-gradient(135deg,"+C.acc+","+C.accD+")",display:"flex",alignItems:"center",justifyContent:"center",fontSize:15,fontWeight:900,color:"#fff",flexShrink:0}}>A</div>{sO&&<div><div style={{fontSize:14,fontWeight:800,color:C.acc,letterSpacing:1,lineHeight:1.1}}>ASSOFRUTTI</div><div style={{fontSize:9,color:C.tM,letterSpacing:2,marginTop:2}}>MAGAZZINO</div></div>}</div>
    <nav style={{flex:1,padding:"10px 8px",overflowY:"auto"}}>{navItems.map(item=><div key={item.id} onClick={()=>goPage(item.id)} style={{display:"flex",alignItems:"center",gap:12,padding:sO?"9px 12px":"9px 14px",borderRadius:8,marginBottom:2,cursor:"pointer",background:page===item.id?C.accL:"transparent",borderLeft:page===item.id?"3px solid "+C.acc:"3px solid transparent",transition:"all .15s"}} onMouseEnter={e=>{if(page!==item.id)e.currentTarget.style.background=C.sfH}} onMouseLeave={e=>{if(page!==item.id)e.currentTarget.style.background="transparent"}}><span style={{fontSize:15,opacity:page===item.id?1:.4,flexShrink:0}}>{item.icon}</span>{sO&&<span style={{fontSize:13,fontWeight:page===item.id?700:400,color:page===item.id?C.acc:C.tD,whiteSpace:"nowrap"}}>{item.label}</span>}</div>)}</nav>
    {!sO&&<div data-no-print onClick={()=>setSO(true)} title={annata==="ALL"?"Tutte le annate (clic per espandere)":"Campagna "+annata} style={{padding:"10px 4px",borderTop:"1px solid "+C.bd,textAlign:"center",cursor:"pointer"}}><div style={{fontSize:8,color:C.tD,letterSpacing:1}}>ANN.</div><div style={{fontSize:14,fontWeight:800,color:C.acc,fontFamily:"'DM Mono',monospace"}}>{annata==="ALL"?"\u2200":String(annata).slice(-2)}</div></div>}
    {sO&&<div style={{padding:"14px 16px",borderTop:"1px solid "+C.bd}}><div style={{marginBottom:12}}><Sel label="Campagna" value={annata} onChange={setAnn} options={[...anni.map(a=>({value:String(a),label:"Campagna "+a})),{value:"ALL",label:"Tutte le annate"}]}/></div><div style={{display:"flex",gap:4,marginBottom:12}}><button onClick={()=>toggleTheme("light")} style={{flex:1,padding:"6px",borderRadius:6,border:"1px solid "+(theme==="light"?C.acc:C.bd),background:theme==="light"?C.accL:"transparent",cursor:"pointer",fontSize:14,display:"flex",alignItems:"center",justifyContent:"center",gap:4}}><span>&#9788;</span><span style={{fontSize:10,color:theme==="light"?C.acc:C.tM,fontWeight:600}}>Chiaro</span></button><button onClick={()=>toggleTheme("dark")} style={{flex:1,padding:"6px",borderRadius:6,border:"1px solid "+(theme==="dark"?C.acc:C.bd),background:theme==="dark"?C.accL:"transparent",cursor:"pointer",fontSize:14,display:"flex",alignItems:"center",justifyContent:"center",gap:4}}><span>&#9790;</span><span style={{fontSize:10,color:theme==="dark"?C.acc:C.tM,fontWeight:600}}>Scuro</span></button></div><div style={{fontSize:12,color:C.tD,marginBottom:6,fontWeight:500}}>{profile?.nome||session?.user?.email}</div><Badge color={isAdm?C.acc:C.b} bg={isAdm?C.accL:C.bD}>{profile?.ruolo||"..."}</Badge><div style={{display:"flex",gap:8,marginTop:12}}><Btn small onClick={loadAll} style={{flex:1,fontSize:11}}>Aggiorna</Btn><Btn small onClick={logout} style={{flex:1,fontSize:11}}>Esci</Btn></div></div>}
    </div><div style={{flex:1,overflow:"auto",padding:"24px 28px",background:C.bg}}>{pg()}</div></div>;
}
